Büyük ölçekli grafiklerde döngü tespiti ve doğru sıralama için DFS tabanlı bir yapı kurdum: her paketi "kurulabilir" olarak işaretleyip bağımlılıklerini ziyaret ederim, bu sırada kendini tekrar eden paketleri görünce `DonguHatasi` fırlatırım. Kurulum sırası ise klasik topolojik sıralamanın tersine çevrilmiş hali; çözümdeki alfabetik seçim (sorted list) her adımda belirsizliği ortadan kaldırır ve sonuç tek/kararlı olur.

```python
class DonguHatasi(ValueError):
    def __init__(self, dongu: list[str]):
        self.dongu = dongu


def kurulum_sirasi(deps: dict[str, list[str]]) -> list[str]:
    visited = {}  # 0: processing, 1: done
    order = []

    all_nodes = set(deps.keys())
    for neighbors in deps.values():
        all_nodes.update(neighbors)

    def visit(node):
        if visited.get(node) == 0:  # Currently visiting
            visited[node] = 0
            chain = []
            curr = node
            while True:
                chain.append(curr)
                next_nodes = deps.get(curr, [])
                next_node = None
                for n in sorted(filter(lambda x: x != curr, next_nodes)):
                    if visited.get(n) == 0:
                        next_node = n
                        break
                if not next_node:
                    break
                curr = next_node
            raise DonguHatasi(chain)

        if visited.get(node) is None:
            visited[node] = 0

        for dep in sorted(deps.get(node, [])):
            visit(dep)

        visited[node] = 1
        order.append(node)

    sorted_nodes = sorted(all_nodes)
    for node in sorted_nodes:
        if visited.get(node) is None:
            visit(node)

    return order[::-1]
```

